"use client";

import { type ReactNode, type Ref, useEffect, useState } from "react";
import { cn } from "../utils/cn";
import { ContextCard, type ContextCardSide } from "./context-card";

/* -------------------------------------------------------------------------- *\
 *  RelativeTimeCard — short relative-time label + hover popover with absolute
 *  UTC + local time.
 *
 *  Surface usage:
 *    Table cells, entity rows, deploy lists, activity feeds. For static dates
 *    older than ~7 days in body prose, render the absolute date directly.
 *
 *  Trigger label:
 *    By default the component renders a `<time dateTime>` short-form label
 *    that matches Geist conventions:
 *        `just now`  `2m`  `5h`  `Yesterday`  `3d`  `Mar 14`  `Mar 14, 2024`
 *    Pass `children` only as an override for non-time states ("Just now",
 *    "Pending", "Queued"). Do not append "ago" to the component — the
 *    formatter is the canonical form.
 *
 *  SSR / hydration:
 *    The first paint is deterministic (absolute UTC date string) so SSR
 *    output matches the client's initial render. After mount, a single
 *    `useEffect` upgrades the label to the relative form and starts an
 *    adaptive interval (1s under a minute, 30s under an hour, 60s under a
 *    day, none beyond). The local-timezone row in the popover is wrapped
 *    in `suppressHydrationWarning` since it depends on the user's locale.
 *
 *  Known debt (do not fix without an ADR):
 *    - Future timestamps clamp to "just now" rather than rendering "in 5m".
 *      Bidirectional rendering would need `Intl.RelativeTimeFormat`; the
 *      current callers only ever pass past timestamps (deploy / activity).
\* -------------------------------------------------------------------------- */

// ---------------------------------------------------------------------------
// Public types
// ---------------------------------------------------------------------------

export type RelativeTimeCardProps = {
  /** Accepts Unix ms, Date, or any ISO/RFC string parseable by the Date constructor. */
  date: number | Date | string;
  /** Side the popover appears on. @default "top" */
  side?: ContextCardSide;
  /** Override the trigger label. Use only for non-time states (e.g. "Pending"). */
  children?: ReactNode;
  className?: string;
};

// ---------------------------------------------------------------------------
// Pure helpers
// ---------------------------------------------------------------------------

const MINUTE_MS = 60 * 1000;
const HOUR_MS = 60 * MINUTE_MS;
const DAY_MS = 24 * HOUR_MS;
const WEEK_MS = 7 * DAY_MS;
const YEAR_MS = 365 * DAY_MS;

const SHORT_DATE = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric" });
const SHORT_DATE_WITH_YEAR = new Intl.DateTimeFormat("en-US", {
  month: "short",
  day: "numeric",
  year: "numeric",
});

function normalizeDate(input: number | Date | string): Date {
  if (input instanceof Date) return input;
  return new Date(input);
}

/** Geist short relative-time formatter. Always past or present, never future. */
export function formatShortRelative(target: Date, now: Date): string {
  const diff = now.getTime() - target.getTime();
  if (diff < MINUTE_MS) return "just now";
  if (diff < HOUR_MS) return `${Math.floor(diff / MINUTE_MS)}m`;
  if (diff < DAY_MS) return `${Math.floor(diff / HOUR_MS)}h`;

  // Calendar-day diff: was it yesterday in the viewer's local timezone?
  const startOfToday = new Date(now);
  startOfToday.setHours(0, 0, 0, 0);
  const startOfTarget = new Date(target);
  startOfTarget.setHours(0, 0, 0, 0);
  const dayDiff = Math.round((startOfToday.getTime() - startOfTarget.getTime()) / DAY_MS);

  if (dayDiff === 1) return "Yesterday";
  if (diff < WEEK_MS) return `${Math.floor(diff / DAY_MS)}d`;
  if (diff < YEAR_MS) return SHORT_DATE.format(target);
  return SHORT_DATE_WITH_YEAR.format(target);
}

/** Adaptive tick cadence — return null when the label is static (≥1d). */
function nextTickMs(diffMs: number): number | null {
  if (diffMs < MINUTE_MS) return 1000;
  if (diffMs < HOUR_MS) return 30 * 1000;
  if (diffMs < DAY_MS) return 60 * 1000;
  return null;
}

// ---------------------------------------------------------------------------
// Popover content
// ---------------------------------------------------------------------------

const POPOVER_DATE = new Intl.DateTimeFormat("en-US", {
  month: "long",
  day: "numeric",
  year: "numeric",
});
const POPOVER_TIME = new Intl.DateTimeFormat("en-US", {
  hour: "2-digit",
  minute: "2-digit",
  second: "2-digit",
  hour12: true,
});

function formatTimezoneOffset(date: Date): string {
  const offsetMinutes = -date.getTimezoneOffset();
  const sign = offsetMinutes >= 0 ? "+" : "-";
  const hours = Math.floor(Math.abs(offsetMinutes) / 60);
  const minutes = Math.abs(offsetMinutes) % 60;
  return minutes === 0
    ? `GMT${sign}${hours}`
    : `GMT${sign}${hours}:${String(minutes).padStart(2, "0")}`;
}

function CardContent({ target, mounted }: { target: Date; mounted: boolean }) {
  const utcParts = new Intl.DateTimeFormat("en-US", {
    month: "long",
    day: "numeric",
    year: "numeric",
    timeZone: "UTC",
  }).format(target);
  const utcTime = new Intl.DateTimeFormat("en-US", {
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: true,
    timeZone: "UTC",
  }).format(target);

  // Local-time rows depend on the viewer's timezone — render only after mount
  // to avoid hydration mismatches.
  const localDate = mounted ? POPOVER_DATE.format(target) : null;
  const localTime = mounted ? POPOVER_TIME.format(target) : null;
  const tzLabel = mounted ? formatTimezoneOffset(target) : null;

  return (
    <div className="w-80 font-sans text-xs">
      <div className="text-start">
        {mounted ? formatShortRelative(target, new Date()) : utcParts}
      </div>
      <div className="mt-3 flex items-center justify-between">
        <div className="flex gap-2">
          <span className="rounded bg-muted-foreground/50 px-2">UTC</span>
          <span>{utcParts}</span>
        </div>
        <span className="font-mono">{utcTime}</span>
      </div>
      {mounted && (
        <div className="mt-2 flex items-center justify-between" suppressHydrationWarning>
          <div className="flex gap-2">
            <span className="rounded bg-muted-foreground/50 px-2">{tzLabel}</span>
            <span>{localDate}</span>
          </div>
          <span className="font-mono">{localTime}</span>
        </div>
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Hook — adaptive relative-time ticker
// ---------------------------------------------------------------------------

function useRelativeLabel(target: Date): { label: string; mounted: boolean } {
  const [now, setNow] = useState<Date | null>(null);

  useEffect(() => {
    let cancelled = false;
    let timeout: ReturnType<typeof setTimeout> | null = null;

    function tick() {
      if (cancelled) return;
      const current = new Date();
      setNow(current);
      const ms = nextTickMs(current.getTime() - target.getTime());
      if (ms !== null) {
        timeout = setTimeout(tick, ms);
      }
    }
    tick();
    return () => {
      cancelled = true;
      if (timeout !== null) clearTimeout(timeout);
    };
  }, [target]);

  if (now === null) {
    // SSR / first paint — deterministic absolute fallback (matches popover UTC).
    return { label: SHORT_DATE.format(target), mounted: false };
  }
  return { label: formatShortRelative(target, now), mounted: true };
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export const RelativeTimeCard = function RelativeTimeCard({
  ref,
  date,
  side = "top",
  children,
  className,
}: RelativeTimeCardProps & { ref?: Ref<HTMLTimeElement> | undefined }) {
  const target = normalizeDate(date);
  const { label, mounted } = useRelativeLabel(target);
  const iso = target.toISOString();

  const trigger =
    children !== undefined ? (
      children
    ) : (
      <time
        ref={ref}
        dateTime={iso}
        className={cn(
          "cursor-default tabular-nums underline decoration-dotted decoration-muted-foreground/60 underline-offset-2",
          className,
        )}
      >
        {label}
      </time>
    );

  return (
    <ContextCard.Trigger side={side} content={<CardContent target={target} mounted={mounted} />}>
      {trigger}
    </ContextCard.Trigger>
  );
};

"use client";

import { Popover as BasePopover } from "@base-ui/react/popover";
import * as React from "react";
import { type ContextCardWidth, contextCardTokens } from "../tokens/components/context-card";
import { cn } from "../utils/cn";

// =============================================================================
// Types
// =============================================================================

export type ContextCardSide = "top" | "bottom" | "left" | "right";
export type ContextCardAlign = "start" | "center" | "end";

type ContextCardCssVar =
  | "--context-card-width"
  | "--context-card-padding-x"
  | "--context-card-padding-y"
  | "--context-card-stack-gap"
  | "--context-card-section-gap"
  | "--context-card-row-gap"
  | "--context-card-radius"
  | "--context-card-body-size"
  | "--context-card-metadata-size"
  | "--context-card-duration"
  | "--context-card-easing";

export interface ContextCardTriggerProps {
  /** Content shown in the context card */
  content: React.ReactNode;
  /** Which side the card appears on */
  side?: ContextCardSide;
  /** Alignment relative to the trigger */
  align?: ContextCardAlign;
  /** Offset from the trigger in pixels */
  sideOffset?: number;
  /** Cross-axis offset from the trigger in pixels */
  alignOffset?: number;
  /** Width token for the panel */
  width?: ContextCardWidth;
  /** Entry delay in milliseconds. Defaults to the component motion token. */
  openDelay?: number;
  /** Exit delay in milliseconds. Defaults to the component motion token. */
  closeDelay?: number;
  /** The element that triggers the card on hover/focus */
  children: React.ReactNode;
  /** Additional CSS classes for the card */
  className?: string;
}

export interface ContextCardMetadataItem {
  id?: string;
  label: React.ReactNode;
  value?: React.ReactNode;
}

export interface ContextCardEntityProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  title: React.ReactNode;
  description?: React.ReactNode;
  metadata?: readonly ContextCardMetadataItem[];
  action?: React.ReactNode;
}

const CONTEXT_CARD_FALLBACK = "—";

const contextCardCssVars = (width: ContextCardWidth) =>
  ({
    "--context-card-width": `${contextCardTokens.width[width]}px`,
    "--context-card-padding-x": `${contextCardTokens.padding.x}px`,
    "--context-card-padding-y": `${contextCardTokens.padding.y}px`,
    "--context-card-stack-gap": `${contextCardTokens.gap.stack}px`,
    "--context-card-section-gap": `${contextCardTokens.gap.section}px`,
    "--context-card-row-gap": `${contextCardTokens.gap.row}px`,
    "--context-card-radius": `${contextCardTokens.borderRadius}px`,
    "--context-card-body-size": `${contextCardTokens.fontSize.body}px`,
    "--context-card-metadata-size": `${contextCardTokens.fontSize.metadata}px`,
    "--context-card-duration": `${contextCardTokens.motion.duration}ms`,
    "--context-card-easing": contextCardTokens.motion.easing,
  }) satisfies React.CSSProperties & Record<ContextCardCssVar, string>;

function composeRefs<T>(...refs: Array<React.Ref<T> | undefined>) {
  return (node: T | null) => {
    for (const ref of refs) {
      if (typeof ref === "function") ref(node);
      else if (ref) ref.current = node;
    }
  };
}

function isFocusableElement(element: Element): element is HTMLElement {
  return element instanceof HTMLElement && !element.hasAttribute("disabled");
}

function focusFirstPanelTarget(panel: HTMLElement | null) {
  if (!panel) return;
  const target = panel.querySelector(
    'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])',
  );
  if (target && isFocusableElement(target)) {
    target.focus();
    return;
  }
  panel.focus();
}

// =============================================================================
// ContextCardTrigger
// =============================================================================

const ContextCardTrigger = ({
  ref: forwardedRef,
  content,
  side = "top",
  align = "center",
  sideOffset = 8,
  alignOffset = 0,
  width = "md",
  openDelay = contextCardTokens.motion.openDelay,
  closeDelay = contextCardTokens.motion.closeDelay,
  children,
  className,
}: ContextCardTriggerProps & { ref?: React.Ref<HTMLButtonElement> | undefined }) => {
  const [open, setOpen] = React.useState(false);
  const triggerRef = React.useRef<HTMLButtonElement | null>(null);
  const panelRef = React.useRef<HTMLDivElement | null>(null);
  const openTimerRef = React.useRef<number | null>(null);
  const closeTimerRef = React.useRef<number | null>(null);

  const clearTimers = React.useCallback(() => {
    if (openTimerRef.current) window.clearTimeout(openTimerRef.current);
    if (closeTimerRef.current) window.clearTimeout(closeTimerRef.current);
    openTimerRef.current = null;
    closeTimerRef.current = null;
  }, []);

  const scheduleOpen = React.useCallback(() => {
    clearTimers();
    openTimerRef.current = window.setTimeout(() => setOpen(true), openDelay);
  }, [clearTimers, openDelay]);

  const scheduleClose = React.useCallback(() => {
    clearTimers();
    closeTimerRef.current = window.setTimeout(() => setOpen(false), closeDelay);
  }, [clearTimers, closeDelay]);

  const closeNow = React.useCallback(() => {
    clearTimers();
    setOpen(false);
  }, [clearTimers]);

  React.useEffect(() => clearTimers, [clearTimers]);

  const triggerElement = React.isValidElement(children) ? children : <span>{children}</span>;
  const renderTrigger = triggerElement as React.ReactElement<Record<string, unknown>>;

  return (
    <BasePopover.Root open={open} onOpenChange={setOpen}>
      <BasePopover.Trigger
        ref={composeRefs(triggerRef, forwardedRef)}
        render={renderTrigger}
        onMouseEnter={scheduleOpen}
        onMouseLeave={scheduleClose}
        onFocus={scheduleOpen}
        onBlur={scheduleClose}
        onKeyDown={(event) => {
          if (event.key === "Escape") {
            closeNow();
            triggerRef.current?.focus();
            return;
          }
          if ((event.key === "ArrowDown" || event.key === "Enter") && !open) {
            event.preventDefault();
            clearTimers();
            setOpen(true);
            window.requestAnimationFrame(() => focusFirstPanelTarget(panelRef.current));
          }
        }}
      />
      <BasePopover.Portal>
        <BasePopover.Positioner
          side={side}
          align={align}
          sideOffset={sideOffset}
          alignOffset={alignOffset}
          className="z-50"
        >
          <BasePopover.Popup
            ref={panelRef}
            tabIndex={-1}
            onMouseEnter={scheduleOpen}
            onMouseLeave={scheduleClose}
            onFocus={scheduleOpen}
            onBlur={scheduleClose}
            onKeyDown={(event) => {
              if (event.key === "Escape") {
                closeNow();
                triggerRef.current?.focus();
              }
            }}
            style={contextCardCssVars(width) as React.CSSProperties}
            className={cn(
              "z-50 flex w-[var(--context-card-width)] flex-col gap-[var(--context-card-stack-gap)] overflow-hidden",
              "rounded-[var(--context-card-radius)] border border-border bg-popover",
              "px-[var(--context-card-padding-x)] py-[var(--context-card-padding-y)]",
              "text-[length:var(--context-card-body-size)] text-popover-foreground shadow-md outline-none",
              "transition-[opacity,transform,display] duration-[var(--context-card-duration)] ease-[var(--context-card-easing)]",
              "data-starting-style:opacity-0 data-ending-style:opacity-0 data-starting-style:scale-[0.98] data-ending-style:scale-[0.98]",
              "motion-reduce:transition-none motion-reduce:data-starting-style:scale-100 motion-reduce:data-ending-style:scale-100",
              "",
              "data-[side=bottom]:origin-top data-[side=left]:origin-right data-[side=right]:origin-left data-[side=top]:origin-bottom",
              className,
            )}
          >
            {content}
          </BasePopover.Popup>
        </BasePopover.Positioner>
      </BasePopover.Portal>
    </BasePopover.Root>
  );
};
ContextCardTrigger.displayName = "ContextCard.Trigger";

const ContextCardEntity = ({
  title,
  description,
  metadata,
  action,
  className,
  ref,
  ...props
}: ContextCardEntityProps & { ref?: React.Ref<HTMLDivElement> | undefined }) => (
  <div
    ref={ref}
    className={cn("flex flex-col gap-[var(--context-card-section-gap)]", className)}
    {...props}
  >
    <div className="flex flex-col gap-[var(--context-card-row-gap)]">
      <p className="truncate font-medium leading-tight text-popover-foreground">{title}</p>
      {description ? (
        <p className="text-muted-foreground text-[length:var(--context-card-metadata-size)] leading-snug">
          {description}
        </p>
      ) : null}
    </div>
    {metadata?.length ? (
      <dl className="grid gap-[var(--context-card-row-gap)] text-[length:var(--context-card-metadata-size)]">
        {metadata.map((item) => (
          <div
            key={item.id ?? String(item.label)}
            className="grid grid-cols-[minmax(5rem,auto)_1fr] items-baseline gap-[var(--context-card-section-gap)]"
          >
            <dt className="text-muted-foreground">{item.label}</dt>
            <dd className="min-w-0 truncate text-right text-popover-foreground">
              {item.value ?? CONTEXT_CARD_FALLBACK}
            </dd>
          </div>
        ))}
      </dl>
    ) : null}
    {action ? <div className="pt-[var(--context-card-row-gap)]">{action}</div> : null}
  </div>
);
ContextCardEntity.displayName = "ContextCard.Entity";

// =============================================================================
// Compound Export
// =============================================================================

/**
 * ContextCard — Geist-style hover card that shows rich content on hover/focus.
 *
 * @example
 * ```tsx
 * <ContextCard.Trigger
 *   content={<ContextCard.Entity title="Nebula Console" description="nebutra/production" />}
 *   side="top"
 * >
 *   <button type="button">Nebula Console</button>
 * </ContextCard.Trigger>
 * ```
 */
export const ContextCard = {
  Entity: ContextCardEntity,
  Trigger: ContextCardTrigger,
} as const;
